mapper.select:
SELECT script.id, script.script_name AS name, script.project_id AS project_id, script.brief_id AS brief_id, COALESCE( NULLIF(brief.product_name, ''), NULLIF(brief.brief_name, ''), CASE WHEN script.brief_id IS NOT NULL THEN CONCAT('Brief #', script.brief_id) END, '未关联 Brief' ) AS brief_name, script.script_type AS type, CASE WHEN script.status = 'pending' THEN 'pending_review' WHEN script.status = 'done' THEN 'approved' ELSE script.status END AS status, script.create_time AS created_at, script.update_time AS updated_at FROM ai_storyboard_script script LEFT JOIN ai_brief brief ON brief.id = script.brief_id AND brief.tenant_id = script.tenant_id WHERE script.deleted = 0 AND script.tenant_id = #{tenantId} AND script.create_by = #{creatorId} AND script.project_id = #{projectId}
AND script.script_name LIKE CONCAT('%', #{keyword}, '%')
AND script.script_type IN
#{scriptType}
AND script.status IN ('pending_review', 'pending')
AND script.status IN ('approved', 'done')
AND script.status = #{status}
ORDER BY CASE WHEN script.brief_id IS NULL THEN 1 ELSE 0 END, script.brief_id ASC, script.update_time DESC, script.id DESC
ORDER BY script.update_time DESC, script.id DESC
